svg.script:
var details, svg;
function init(evt) {
  details = document.getElementById("details").firstChild;
  svg = document.getElementsByTagName("svg")[0];
  trimLabels();
}
function trimLabels() {
  var gs = svg.querySelectorAll(".func_g");
  for (var i = 0; i < gs.length; i++) {
    var r = gs[i].querySelector("rect");
    var t = gs[i].querySelector("text");
    if (!r || !t || !t.textContent.trim()) continue;
    try {
      if (t.getBBox().width > parseFloat(r.getAttribute("width")) - 6) {
        t.style.display = "none";
      }
    } catch (e) {}
  }
}
function s(node) {
  var t = node.querySelector("title");
  if (t) details.nodeValue = t.textContent;
}
function c() { details.nodeValue = " "; }
function qchild(node, sel) {
  var nl = node.querySelectorAll(sel);
  return nl.length ? nl[0] : null;
}
function save(e, a) {
  if (!e.hasAttribute("_o_" + a) && e.hasAttribute(a))
    e.setAttribute("_o_" + a, e.getAttribute(a));
}
function load(e, a) {
  if (e.hasAttribute("_o_" + a)) {
    e.setAttribute(a, e.getAttribute("_o_" + a));
    e.removeAttribute("_o_" + a);
  }
}
function walk_reset(n) {
  if (n.attributes) { load(n, "x"); load(n, "width"); }
  for (var i = 0; i < n.childNodes.length; i++) walk_reset(n.childNodes[i]);
}
function walk_child(n, x0, ratio) {
  if (n.attributes) {
    var xa = n.attributes["x"], wa = n.attributes["width"];
    if (xa) {
      save(n, "x");
      xa.value = (parseFloat(xa.value) - x0 - 10) * ratio + 10;
    }
    if (wa) { save(n, "width"); wa.value = parseFloat(wa.value) * ratio; }
    if (xa && n.tagName === "text") {
      var r = qchild(n.parentNode, "rect");
      if (r) xa.value = parseFloat(r.getAttribute("x")) + 3;
    }
  }
  for (var i = 0; i < n.childNodes.length; i++) walk_child(n.childNodes[i], x0 - 10, ratio);
}
function walk_parent(n) {
  if (n.attributes) {
    var svgW = parseInt(svg.getAttribute("width")) - 20;
    var xa = n.attributes["x"], wa = n.attributes["width"];
    if (xa) { save(n, "x"); xa.value = 10; }
    if (wa) { save(n, "width"); wa.value = svgW; }
  }
  for (var i = 0; i < n.childNodes.length; i++) walk_parent(n.childNodes[i]);
}
function zoom(node) {
  var r = qchild(node, "rect");
  if (!r) return;
  var rx = parseFloat(r.getAttribute("x")),
      rw = parseFloat(r.getAttribute("width")),
      ry = parseFloat(r.getAttribute("y")),
      svgW = parseInt(svg.getAttribute("width")),
      ratio = (svgW - 20) / rw;
  document.getElementById("unzoom").style.opacity = "1";
  var gs = svg.getElementsByTagName("g");
  for (var i = 0; i < gs.length; i++) {
    var g = gs[i];
    if (g.getAttribute("class") !== "func_g") continue;
    var e = qchild(g, "rect");
    if (!e) continue;
    var ex = parseFloat(e.getAttribute("x")),
        ew = parseFloat(e.getAttribute("width")),
        ey = parseFloat(e.getAttribute("y"));
    if (ex <= rx && (ex + ew + 2) >= (rx + rw) && ey <= ry) {
      walk_parent(g); g.style.opacity = "0.5";
    } else if (ex < rx + rw && ex + ew > rx && ey > ry) {
      walk_child(g, rx, ratio); g.style.opacity = "1";
    } else {
      g.style.display = "none";
    }
  }
}
function unzoom() {
  document.getElementById("unzoom").style.opacity = "0.1";
  var gs = svg.getElementsByTagName("g");
  for (var i = 0; i < gs.length; i++) {
    var g = gs[i];
    if (g.getAttribute("class") !== "func_g") continue;
    walk_reset(g);
    g.style.opacity = "1";
    g.style.display = "";
  }
}
function search_prompt() {
  var term = prompt("Search (regexp, e.g. ssl|httpx):", "");
  if (!term) return;
  var re = new RegExp(term);
  var gs = svg.getElementsByTagName("g");
  for (var i = 0; i < gs.length; i++) {
    var g = gs[i];
    if (g.getAttribute("class") !== "func_g") continue;
    var t = g.querySelector("title"), e = qchild(g, "rect");
    if (!t || !e) continue;
    if (t.textContent.match(re)) {
      save(e, "fill"); e.setAttribute("fill", "rgb(230,0,10)");
    } else {
      e.setAttribute("fill", "rgb(200,200,200)");
    }
  }
}
